	"grid-dots": "<script lang=\"ts\">\n\timport { motion } from 'motion-sv';\n\n\tconst Div = motion.div;\n</script>\n\n<div class=\"grid grid-cols-3 gap-1.5\">\n\t{#each [0, 1, 2, 3, 4, 5, 6, 7, 8] as i}\n\t\t<Div\n\t\t\tclass=\"w-2.5 h-2.5 bg-zinc-800 dark:bg-white rounded-full\"\n\t\t\tanimate={{ scale: [1, 0.5, 1], opacity: [1, 0.3, 1] }}\n\t\t\ttransition={{\n\t\t\t\tduration: 1.5,\n\t\t\t\trepeat: Infinity,\n\t\t\t\tdelay: (i % 3) * 0.2 + Math.floor(i / 3) * 0.2,\n\t\t\t\tease: 'easeInOut'\n\t\t\t}}\n\t\t/>\n\t{/each}\n</div>\n",
