	"Text Shimmer": "\n<div class=\"relative text-zinc-200 font-medium text-lg\">\n\tThinking\n\t<div class=\"absolute inset-0 text-zinc-900 dark:text-white shimmer-sweep\">\n\t\tThinking\n\t</div>\n</div>\n\n<style>\n\t.shimmer-sweep {\n\t\t-webkit-mask-image: linear-gradient(90deg, transparent 0%, black 50%, transparent 100%);\n\t\t-webkit-mask-size: 200% 100%;\n\t\tmask-image: linear-gradient(90deg, transparent 0%, black 50%, transparent 100%);\n\t\tmask-size: 200% 100%;\n\t\tanimation: shimmer-sweep 1.5s linear infinite;\n\t}\n\n\t@keyframes shimmer-sweep {\n\t\tfrom {\n\t\t\t-webkit-mask-position: 100% 0%;\n\t\t\tmask-position: 100% 0%;\n\t\t}\n\t\tto {\n\t\t\t-webkit-mask-position: -100% 0%;\n\t\t\tmask-position: -100% 0%;\n\t\t}\n\t}\n</style>\n",
	"trailing-dots": "<script lang=\"ts\">\n\timport { motion } from 'motion-sv';\n\n\tconst Div = motion.div;\n</script>\n\n<div class=\"relative w-10 h-10\">\n\t{#each [0, 1, 2, 3, 4] as i}\n\t\t<Div\n\t\t\tclass=\"absolute inset-0\"\n\t\t\tanimate={{ rotate: 360 }}\n\t\t\ttransition={{ duration: 1.5, repeat: Infinity, delay: i * 0.1, ease: 'easeInOut' }}\n\t\t>\n\t\t\t<div\n\t\t\t\tclass=\"w-2 h-2 rounded-full absolute top-0 left-1/2 -ml-1 {i === 0\n\t\t\t\t\t? 'bg-zinc-800 dark:bg-white'\n\t\t\t\t\t: 'bg-zinc-400 dark:bg-zinc-200'}\"\n\t\t\t\tstyle=\"opacity: {1 - i * 0.2}\"\n\t\t\t></div>\n\t\t</Div>\n\t{/each}\n</div>\n",
	"TrailingDots": "<script lang=\"ts\">\n\timport { motion } from 'motion-sv';\n\n\tconst Div = motion.div;\n</script>\n\n<div class=\"relative w-10 h-10\">\n\t{#each [0, 1, 2, 3, 4] as i}\n\t\t<Div\n\t\t\tclass=\"absolute inset-0\"\n\t\t\tanimate={{ rotate: 360 }}\n\t\t\ttransition={{ duration: 1.5, repeat: Infinity, delay: i * 0.1, ease: 'easeInOut' }}\n\t\t>\n\t\t\t<div\n\t\t\t\tclass=\"w-2 h-2 rounded-full absolute top-0 left-1/2 -ml-1 {i === 0\n\t\t\t\t\t? 'bg-zinc-800 dark:bg-white'\n\t\t\t\t\t: 'bg-zinc-400 dark:bg-zinc-200'}\"\n\t\t\t\tstyle=\"opacity: {1 - i * 0.2}\"\n\t\t\t></div>\n\t\t</Div>\n\t{/each}\n</div>\n",
	"Trailing Dots": "<script lang=\"ts\">\n\timport { motion } from 'motion-sv';\n\n\tconst Div = motion.div;\n</script>\n\n<div class=\"relative w-10 h-10\">\n\t{#each [0, 1, 2, 3, 4] as i}\n\t\t<Div\n\t\t\tclass=\"absolute inset-0\"\n\t\t\tanimate={{ rotate: 360 }}\n\t\t\ttransition={{ duration: 1.5, repeat: Infinity, delay: i * 0.1, ease: 'easeInOut' }}\n\t\t>\n\t\t\t<div\n\t\t\t\tclass=\"w-2 h-2 rounded-full absolute top-0 left-1/2 -ml-1 {i === 0\n\t\t\t\t\t? 'bg-zinc-800 dark:bg-white'\n\t\t\t\t\t: 'bg-zinc-400 dark:bg-zinc-200'}\"\n\t\t\t\tstyle=\"opacity: {1 - i * 0.2}\"\n\t\t\t></div>\n\t\t</Div>\n\t{/each}\n</div>\n",
	"triple-dot-spinner": "<script lang=\"ts\">\n\timport { motion } from 'motion-sv';\n\n\tconst Div = motion.div;\n</script>\n\n<Div\n\tclass=\"relative w-10 h-10\"\n\tanimate={{ rotate: 360 }}\n\ttransition={{ duration: 2, repeat: Infinity, ease: 'linear' }}\n>\n\t{#each [0, 1, 2] as i}\n\t\t<div\n\t\t\tclass=\"absolute top-0 left-1/2 w-2 h-2 bg-zinc-800 dark:bg-white rounded-full -ml-1 origin-[4px_20px]\"\n\t\t\tstyle=\"transform: rotate({i * 120}deg)\"\n\t\t></div>\n\t{/each}\n</Div>\n",
